/// C-FFI dispatch descriptor for SunSpec model 711. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_711: StaticModelSpec = StaticModelSpec {
    id: 711,
    length: model_711_c_length,
    writable: true,
    visit_read: model_711_c_visit_read,
    visit_write: model_711_c_visit_write,
};

fn model_711_c_length(repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model711 {
        stored_control_count: repeat_count_0,
    })
    .model_length()
}

/// # Safety
/// For `kind` 1 or 2, `adapter` must point to a live `Model711{Stateful,Callback}Adapter`,
/// valid for the duration of the call.
unsafe fn model_711_c_visit_read(
    kind: u8,
    adapter: *const c_void,
    repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model711 {
        stored_control_count: repeat_count_0,
    };
    let adapter: Option<&dyn ReadAdapter> = match kind {
        2 => Some(unsafe { &*(adapter as *const Model711CallbackAdapter) } as &dyn ReadAdapter),
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_711_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_711_c_visit_write(
    kind: u8,
    adapter: *mut c_void,
    repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model711 {
        stored_control_count: repeat_count_0,
    };
    let adapter: Option<&mut dyn WriteAdapter> = match kind {
        2 => {
            Some(unsafe { &mut *(adapter as *mut Model711CallbackAdapter) } as &mut dyn WriteAdapter)
        }
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}
